 "content": "from collections import deque


def transform(grid):
    """Tile each zero panel with the local colored motif's periodic pattern."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 8 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            marks = [(y, x) for y, x in comp if grid[y][x] not in (0, 8)]
            if not marks:
                continue
            top, bottom = min(y for y, _ in marks), max(y for y, _ in marks)
            left, right = min(x for _, x in marks), max(x for _, x in marks)
            th, tw = bottom - top + 1, right - left + 1
            tile = [[grid[top + i][left + j] for j in range(tw)] for i in range(th)]
            for y, x in comp:
                out[y][x] = tile[(y - top) % th][(x - left) % tw]
    return out
